{$ param eyebrow label="Eyebrow Text" default="" description="Small label above the title (optional)." $}
{$ param title label="Title" default="Headline goes here" description="Main heading." $}
{$ param image_url label="Image URL" default="https://picsum.photos/400/400" description="Hero image URL." type="fileurl" $}
{$ param image_alt label="Image Alt Text" default="" description="Accessibility description of the image." $}
{$ param cta_label label="CTA Label" default="Learn More" description="Button label (leave blank to hide)." $}
{$ param cta_href label="CTA URL" default="#" description="Destination URL." $}

<div class="flex flex-col sm:flex-row justify-center items-center max-w-[960px] mx-auto mb-8 backport">
  <img src="{$= image_url $}" alt="{$= image_alt $}" class="self-center max-w-[200px] mr-4 mb-4 sm:mb-0" />
  <div class="text-center sm:text-left">
    {$ if eyebrow $}<span class="ss-xxs text-orange uppercase font-bold">{$= eyebrow $}</span>{$ /if $}
    <h1 class="ss-large mb-4">{$= title $}</h1>
    {$ slot body $}
      <p>Introductory body copy.</p>
    {$ /slot $}
    {$ if cta_label $}<a href="{$= cta_href $}" class="btn btn-primary">{$= cta_label $}</a>{$ /if $}
  </div>
</div>
